CREATE TABLE proveedores (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT UNIQUE);
CREATE TABLE productos (sku TEXT PRIMARY KEY, id_loyverse TEXT, variant_id TEXT, nombre TEXT, categoria TEXT, proveedor TEXT, barcode TEXT, precio REAL, costo REAL, stock REAL, sold_by_weight INTEGER DEFAULT 0, track_stock INTEGER DEFAULT 1, con_iva INTEGER DEFAULT 0, sector TEXT, imagen_url TEXT, proveedor_id INTEGER REFERENCES proveedores(id), descripcion TEXT, fecha_creacion TEXT);
CREATE TABLE fiados (id INTEGER PRIMARY KEY AUTOINCREMENT, cliente_id TEXT, receipt_id_loyverse TEXT NOT NULL UNIQUE, monto_total REAL NOT NULL, estado TEXT NOT NULL DEFAULT 'abierto', fecha_hora TEXT NOT NULL);
CREATE TABLE auditoria (id INTEGER PRIMARY KEY AUTOINCREMENT, fecha TEXT, accion TEXT, sku TEXT, producto TEXT, categoria TEXT, id_loyverse TEXT, stock REAL, motivo TEXT, responsable TEXT, cantidad REAL);
CREATE TABLE categorias_loyverse (id TEXT PRIMARY KEY, nombre TEXT);
CREATE TABLE clasificacion_abc (sku TEXT PRIMARY KEY, venta_total REAL, pct_participacion REAL, pct_acumulado REAL, clase TEXT, periodo_dias INTEGER, calculado_en TEXT);
CREATE TABLE config (clave TEXT PRIMARY KEY, valor TEXT);
CREATE TABLE config_categorias (categoria TEXT PRIMARY KEY, tipo TEXT);
CREATE TABLE config_multiplo_producto (sku TEXT PRIMARY KEY, multiplo INTEGER, empaque INTEGER, palabra TEXT, actualizado_en TEXT);
CREATE TABLE config_vida_util (categoria TEXT PRIMARY KEY, dias_alerta INTEGER NOT NULL, tipo TEXT NOT NULL, nota TEXT);
CREATE TABLE configuracion (clave TEXT PRIMARY KEY, valor TEXT NOT NULL);
CREATE TABLE control_dedup (clave TEXT PRIMARY KEY);
CREATE TABLE control_tx (ym TEXT PRIMARY KEY, n_transacciones INTEGER NOT NULL DEFAULT 0);
CREATE TABLE diccionario_aprendido (patron TEXT PRIMARY KEY, tipo TEXT NOT NULL, categoria TEXT NOT NULL, nombre TEXT NOT NULL, aprendido_en TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE facturas_calculos (id INTEGER PRIMARY KEY AUTOINCREMENT, factura_id TEXT, fecha TEXT, producto TEXT, costo_unitario REAL, margen REAL, precio_venta REAL, precio_psicologico REAL, categoria TEXT, responsable TEXT);
CREATE TABLE favoritos (sku TEXT PRIMARY KEY, agregado_en TEXT);
CREATE TABLE fiados_lineas (id INTEGER PRIMARY KEY AUTOINCREMENT, fiado_id INTEGER NOT NULL REFERENCES fiados(id), sku TEXT NOT NULL, producto_nombre TEXT, cantidad REAL NOT NULL, precio_unitario REAL NOT NULL, receipt_line_item_id TEXT);
CREATE TABLE fiados_refunds_linea_manual (receipt_refund_numero TEXT PRIMARY KEY, fiado_id INTEGER NOT NULL, creado TEXT NOT NULL);
CREATE TABLE historial_precios (id INTEGER PRIMARY KEY AUTOINCREMENT, sku TEXT NOT NULL, fecha TEXT, precio_antes REAL, precio_despues REAL, costo_antes REAL, costo_despues REAL, responsable TEXT);
CREATE TABLE llegadas (id INTEGER PRIMARY KEY AUTOINCREMENT, fecha_deteccion TEXT, sku TEXT, nombre TEXT, categoria TEXT, unidad TEXT, stock_antes REAL, stock_despues REAL, aumento REAL, estado TEXT DEFAULT 'pendiente', fecha_vencimiento_asignada TEXT, fecha_resolucion TEXT);
CREATE TABLE logs (id INTEGER PRIMARY KEY AUTOINCREMENT, fecha TEXT, mensaje TEXT);
CREATE TABLE mermas (id INTEGER PRIMARY KEY AUTOINCREMENT, fecha TEXT, sku TEXT, producto TEXT, categoria TEXT, unidad TEXT, lote TEXT, cantidad REAL, costo_unitario REAL, costo_total REAL, motivo TEXT, estado_costo TEXT, responsable TEXT, origen TEXT);
CREATE TABLE pagos_fiado (id INTEGER PRIMARY KEY AUTOINCREMENT, cliente_id TEXT, fiado_id INTEGER NOT NULL REFERENCES fiados(id), monto REAL NOT NULL, fecha_hora TEXT NOT NULL, metodo_pago TEXT NOT NULL, receipt_id_loyverse_abono TEXT NOT NULL, receipt_line_item_id_abono TEXT);
CREATE TABLE pedidos_pendientes (id INTEGER PRIMARY KEY AUTOINCREMENT, fecha TEXT, sku TEXT, barcode TEXT, producto TEXT, proveedor TEXT, cantidad REAL, estado TEXT DEFAULT 'confirmado', nombre TEXT, canal TEXT, costo_unitario REAL DEFAULT 0, costo_total REAL DEFAULT 0, fecha_llegada_estimada TEXT);
CREATE TABLE por_revisar (id INTEGER PRIMARY KEY AUTOINCREMENT, fecha TEXT, n_operacion TEXT, descripcion TEXT NOT NULL, monto INTEGER NOT NULL, motivo TEXT, archivo TEXT, creado_en TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE prestamos (id INTEGER PRIMARY KEY AUTOINCREMENT, fecha TEXT NOT NULL, sucursal TEXT NOT NULL, direccion TEXT NOT NULL, sku TEXT NOT NULL, producto TEXT, cantidad REAL NOT NULL, unidad TEXT, costo_unitario REAL, costo_total REAL, estado TEXT NOT NULL DEFAULT 'pendiente', fecha_devolucion TEXT, responsable TEXT, nota TEXT);
CREATE TABLE producto_clasificacion_aprendida (patron TEXT PRIMARY KEY, proveedor_id INTEGER, sector TEXT, actualizado_en TEXT);
CREATE TABLE producto_proveedor_extra (sku TEXT NOT NULL, proveedor_id INTEGER NOT NULL REFERENCES proveedores(id), PRIMARY KEY (sku, proveedor_id));
CREATE TABLE push_subscriptions (endpoint TEXT PRIMARY KEY, p256dh TEXT, auth TEXT, creado TEXT);
CREATE TABLE registros (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL, fecha TEXT NOT NULL, categoria TEXT NOT NULL, tipo TEXT NOT NULL CHECK (tipo IN ('INGRESO','COSTOS','GASTO OPE','MERMA','PLASTICOS','RETIRO_UTILIDAD','PRESTAMO','IMPUESTOS','INVERSION','TRASPASO_INTERNO')), cuenta TEXT NOT NULL CHECK (cuenta IN ('BANCO','EFECTIVO')), monto INTEGER NOT NULL, n_operacion TEXT NOT NULL UNIQUE, origen TEXT, subtipo_original TEXT, creado_en TEXT NOT NULL DEFAULT (datetime('now')), actualizado_en TEXT);
CREATE TABLE riesgo_excluidos (sku TEXT PRIMARY KEY, agregado_en TEXT, fecha TEXT, responsable TEXT);
CREATE TABLE sectores (id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT UNIQUE);
CREATE TABLE sectores_personalizados (nombre TEXT PRIMARY KEY);
CREATE TABLE vencimientos (id INTEGER PRIMARY KEY AUTOINCREMENT, fecha_ingreso TEXT, sku TEXT, producto TEXT, categoria TEXT, unidad TEXT, lote TEXT, cantidad REAL, fecha_vencimiento TEXT, estado TEXT, fecha_revision TEXT, revisado_por TEXT, fecha_retiro TEXT, descuento_activo INTEGER DEFAULT 0, precio_original REAL, precio_aplicado REAL, cant_vendida_desc REAL DEFAULT 0, cant_merma_desc REAL DEFAULT 0, fecha_descuento_aplicado TEXT, motivo_cierre TEXT, merma_id INTEGER, prioridad TEXT, accion TEXT, precio_recomendado REAL, costo_usado REAL, costo_origen TEXT, monto_descuento REAL);
CREATE TABLE ventas (receipt_id TEXT, sku TEXT, cantidad REAL, fecha_venta TEXT, venta REAL DEFAULT 0, utilidad REAL DEFAULT 0, PRIMARY KEY (receipt_id, sku));
CREATE TABLE ventas_diarias_historico (fecha TEXT NOT NULL, sku TEXT NOT NULL, unidades REAL NOT NULL, venta INTEGER NOT NULL, utilidad INTEGER NOT NULL, PRIMARY KEY (fecha, sku));
CREATE TABLE webhook_eventos (event_id TEXT PRIMARY KEY, tipo TEXT, recibido_en TEXT);
CREATE VIEW ventas_diarias AS SELECT fecha_venta AS fecha, sku, SUM(cantidad) AS unidades, SUM(venta) AS venta, SUM(utilidad) AS utilidad FROM ventas GROUP BY fecha_venta, sku;
CREATE INDEX idx_fiados_cliente ON fiados(cliente_id);
CREATE INDEX idx_fiados_estado ON fiados(estado);
CREATE INDEX idx_fiados_lineas_fiado ON fiados_lineas(fiado_id);
CREATE INDEX idx_historial_precios_sku ON historial_precios (sku);
CREATE INDEX idx_pagos_fiado_cliente ON pagos_fiado(cliente_id);
CREATE INDEX idx_pagos_fiado_fiado ON pagos_fiado(fiado_id);
CREATE INDEX idx_porrevisar_fecha ON por_revisar(fecha);
CREATE INDEX idx_registros_categoria ON registros(categoria);
CREATE INDEX idx_registros_fecha ON registros(fecha);
CREATE INDEX idx_registros_tipo ON registros(tipo);
CREATE INDEX idx_ventas_fecha ON ventas (fecha_venta);
